-- DESIGN CANDIDATE 1.0, 2026-10-30. NOT a deployed service migration.
-- Run only against an isolated empty database for design verification.
-- UUIDs are generated by the application. No cross-service foreign keys.
BEGIN;
CREATE SCHEMA fulfillment;

CREATE TABLE fulfillment.order_guards (
    order_id uuid PRIMARY KEY,
    highest_generation bigint NOT NULL DEFAULT 0 CHECK (highest_generation >= 0),
    accepted_task_id uuid UNIQUE,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE TABLE fulfillment.admissions (
    order_id uuid NOT NULL REFERENCES fulfillment.order_guards(order_id),
    generation bigint NOT NULL CHECK (generation > 0),
    state text NOT NULL CHECK (state IN ('OPEN','ACCEPTED','CANCELLED')),
    resource_version bigint NOT NULL CHECK (resource_version > 0),
    task_id uuid,
    items_digest text CHECK (items_digest ~ '^[0-9a-f]{64}$'),
    warehouse_id text,
    permit_id text,
    decision_id uuid,
    decision_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    PRIMARY KEY (order_id,generation),
    CHECK (state = 'OPEN' OR (decision_id IS NOT NULL AND decision_at IS NOT NULL)),
    CHECK ((state = 'ACCEPTED') = (task_id IS NOT NULL)),
    CHECK (state <> 'ACCEPTED' OR (items_digest IS NOT NULL AND warehouse_id IS NOT NULL AND permit_id IS NOT NULL))
);

CREATE TABLE fulfillment.tasks (
    task_id uuid PRIMARY KEY,
    order_id uuid NOT NULL UNIQUE REFERENCES fulfillment.order_guards(order_id),
    ready_generation bigint NOT NULL CHECK (ready_generation > 0),
    workflow_state text NOT NULL CHECK (workflow_state IN ('READY','ASSIGNED','IN_PROGRESS','BLOCKED','COMPLETED')),
    resume_state text CHECK (resume_state IN ('READY','ASSIGNED','IN_PROGRESS')),
    version bigint NOT NULL CHECK (version > 0),
    items_digest text NOT NULL CHECK (items_digest ~ '^[0-9a-f]{64}$'),
    warehouse_id text NOT NULL CHECK (length(warehouse_id) > 0),
    channel text NOT NULL,
    cohort text NOT NULL CHECK (cohort IN ('DOMAIN_TEST','INTEGRATED_V2')),
    assignee_id uuid,
    input_snapshot_id text NOT NULL,
    input_snapshot_version bigint NOT NULL CHECK (input_snapshot_version > 0),
    input_snapshot jsonb NOT NULL CHECK (jsonb_typeof(input_snapshot) = 'object'),
    policy_version text NOT NULL,
    policy_snapshot jsonb NOT NULL CHECK (jsonb_typeof(policy_snapshot) = 'object'),
    reservation_id uuid NOT NULL,
    allocation_version bigint NOT NULL CHECK (allocation_version > 0),
    allocation_snapshot jsonb NOT NULL CHECK (jsonb_typeof(allocation_snapshot) = 'object'),
    evidence_mode text NOT NULL CHECK (evidence_mode IN ('OPTIONAL','VIDEO_REQUIRED')),
    packing_due_at timestamptz,
    deadline_revision bigint NOT NULL DEFAULT 1 CHECK (deadline_revision > 0),
    admitted_at timestamptz NOT NULL,
    started_at timestamptz,
    completed_at timestamptz,
    updated_at timestamptz NOT NULL,
    FOREIGN KEY (order_id,ready_generation) REFERENCES fulfillment.admissions(order_id,generation),
    CHECK ((workflow_state = 'BLOCKED') = (resume_state IS NOT NULL)),
    CHECK (workflow_state NOT IN ('ASSIGNED','IN_PROGRESS') OR assignee_id IS NOT NULL),
    CHECK ((workflow_state = 'COMPLETED') = (completed_at IS NOT NULL)),
    CHECK (cohort <> 'INTEGRATED_V2' OR evidence_mode = 'VIDEO_REQUIRED')
);
ALTER TABLE fulfillment.order_guards ADD CONSTRAINT guard_accepted_task_fk
    FOREIGN KEY (accepted_task_id) REFERENCES fulfillment.tasks(task_id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE fulfillment.admissions ADD CONSTRAINT admission_task_fk
    FOREIGN KEY (task_id) REFERENCES fulfillment.tasks(task_id) DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE fulfillment.task_lines (
    line_id uuid PRIMARY KEY,
    task_id uuid NOT NULL REFERENCES fulfillment.tasks(task_id),
    order_line_id uuid NOT NULL,
    sku_code text NOT NULL CHECK (sku_code ~ '^[!-~]+$'),
    product_name text NOT NULL,
    packaging_text text NOT NULL,
    required_quantity integer NOT NULL CHECK (required_quantity > 0),
    fragile boolean NOT NULL,
    UNIQUE (task_id,order_line_id),
    UNIQUE (task_id,line_id)
);
CREATE TABLE fulfillment.pick_allocations (
    allocation_id uuid PRIMARY KEY,
    task_id uuid NOT NULL,
    line_id uuid NOT NULL,
    batch_id uuid NOT NULL,
    batch_code text NOT NULL,
    allocated_quantity integer NOT NULL CHECK (allocated_quantity > 0),
    counted_quantity integer NOT NULL DEFAULT 0 CHECK (counted_quantity >= 0 AND counted_quantity <= allocated_quantity),
    allocation_version bigint NOT NULL CHECK (allocation_version > 0),
    batch_valid_until timestamptz NOT NULL,
    eligibility_revision bigint NOT NULL CHECK (eligibility_revision > 0),
    last_validation_id text,
    last_validated_at timestamptz,
    counted_by uuid,
    counted_at timestamptz,
    FOREIGN KEY (task_id,line_id) REFERENCES fulfillment.task_lines(task_id,line_id),
    UNIQUE (task_id,line_id,batch_id)
);
CREATE TABLE fulfillment.checklist_items (
    task_id uuid NOT NULL REFERENCES fulfillment.tasks(task_id),
    item_code text NOT NULL,
    definition text NOT NULL,
    policy_version text NOT NULL,
    required boolean NOT NULL,
    result text NOT NULL DEFAULT 'PENDING' CHECK (result IN ('PENDING','PASS','FAIL')),
    note text,
    confirmed_by uuid,
    confirmed_at timestamptz,
    PRIMARY KEY (task_id,item_code),
    CHECK (result = 'PENDING' OR (confirmed_by IS NOT NULL AND confirmed_at IS NOT NULL))
);
CREATE TABLE fulfillment.task_blocks (
    block_id uuid PRIMARY KEY,
    task_id uuid NOT NULL REFERENCES fulfillment.tasks(task_id),
    source text NOT NULL,
    source_reference text NOT NULL,
    reason_code text NOT NULL,
    status text NOT NULL CHECK (status IN ('ACTIVE','RESOLVED')),
    created_by text NOT NULL,
    created_at timestamptz NOT NULL,
    resolved_by text,
    resolved_at timestamptz,
    resolution_reason text,
    CHECK (status <> 'RESOLVED' OR (resolved_by IS NOT NULL AND resolved_at IS NOT NULL AND resolution_reason IS NOT NULL))
);
CREATE UNIQUE INDEX task_block_active_source ON fulfillment.task_blocks(task_id,source,source_reference) WHERE status = 'ACTIVE';

CREATE TABLE fulfillment.packages (
    package_id uuid PRIMARY KEY,
    task_id uuid NOT NULL UNIQUE REFERENCES fulfillment.tasks(task_id),
    state text NOT NULL CHECK (state IN ('DRAFT','SEALED','VOID')),
    seal_code text UNIQUE CHECK (seal_code ~ '^[A-Z0-9][A-Z0-9-]{5,79}$'),
    weight_grams integer CHECK (weight_grams > 0),
    length_cm integer CHECK (length_cm > 0),
    width_cm integer CHECK (width_cm > 0),
    height_cm integer CHECK (height_cm > 0),
    fragile boolean,
    primary_evidence_id uuid,
    sealed_task_version bigint,
    sealed_at timestamptz,
    created_at timestamptz NOT NULL,
    UNIQUE (task_id,package_id),
    CHECK (state <> 'SEALED' OR (seal_code IS NOT NULL AND weight_grams IS NOT NULL AND length_cm IS NOT NULL AND width_cm IS NOT NULL AND height_cm IS NOT NULL AND fragile IS NOT NULL AND sealed_task_version IS NOT NULL AND sealed_task_version > 0 AND sealed_at IS NOT NULL))
);
CREATE TABLE fulfillment.media_files (
    file_id uuid PRIMARY KEY,
    task_id uuid NOT NULL,
    package_id uuid NOT NULL,
    purpose text NOT NULL CHECK (purpose = 'PACKING_VIDEO'),
    uploader_id uuid NOT NULL,
    status text NOT NULL CHECK (status IN ('CREATED','UPLOADED','VERIFYING','VERIFIED','REJECTED','EXPIRED','DELETE_PENDING','DELETED')),
    object_key text NOT NULL UNIQUE,
    final_object_key text UNIQUE,
    object_version text,
    declared_size_bytes bigint NOT NULL CHECK (declared_size_bytes > 0),
    actual_size_bytes bigint CHECK (actual_size_bytes > 0),
    media_type text NOT NULL,
    declared_sha256 text NOT NULL CHECK (declared_sha256 ~ '^[0-9a-f]{64}$'),
    verified_sha256 text CHECK (verified_sha256 ~ '^[0-9a-f]{64}$'),
    scan_status text NOT NULL DEFAULT 'PENDING' CHECK (scan_status IN ('PENDING','SAFE','REJECTED','UNKNOWN')),
    scanner_policy_version text NOT NULL,
    session_expires_at timestamptz NOT NULL,
    verified_at timestamptz,
    attached_at timestamptz,
    retention_until timestamptz NOT NULL,
    legal_hold boolean NOT NULL DEFAULT false,
    version bigint NOT NULL CHECK (version > 0),
    created_at timestamptz NOT NULL,
    FOREIGN KEY (task_id,package_id) REFERENCES fulfillment.packages(task_id,package_id),
    CHECK (status <> 'VERIFIED' OR (final_object_key IS NOT NULL AND object_version IS NOT NULL AND verified_sha256 IS NOT NULL AND scan_status = 'SAFE' AND verified_at IS NOT NULL)),
    CHECK (attached_at IS NULL OR verified_at IS NOT NULL)
);
ALTER TABLE fulfillment.packages ADD CONSTRAINT package_primary_evidence_fk
    FOREIGN KEY (primary_evidence_id) REFERENCES fulfillment.media_files(file_id) DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE fulfillment.task_revisions (
    task_id uuid NOT NULL REFERENCES fulfillment.tasks(task_id),
    resource_version bigint NOT NULL CHECK (resource_version > 0),
    kind text NOT NULL CHECK (kind IN ('PACKING_ACCEPTED','TASK_UPDATED','PACKING_SEALED')),
    order_id uuid NOT NULL,
    ready_generation bigint NOT NULL CHECK (ready_generation > 0),
    items_digest text NOT NULL CHECK (items_digest ~ '^[0-9a-f]{64}$'),
    warehouse_id text NOT NULL,
    package_id uuid,
    seal_code text,
    occurred_at timestamptz NOT NULL,
    snapshot jsonb NOT NULL CHECK (jsonb_typeof(snapshot) = 'object'),
    PRIMARY KEY (task_id,resource_version),
    CHECK (kind <> 'PACKING_SEALED' OR (package_id IS NOT NULL AND seal_code IS NOT NULL))
);
CREATE TABLE fulfillment.command_registry (
    caller_id text NOT NULL,
    action text NOT NULL,
    order_id uuid NOT NULL REFERENCES fulfillment.order_guards(order_id),
    command_key text NOT NULL CHECK (length(command_key) BETWEEN 16 AND 128 AND command_key ~ '^[!-~]+$'),
    request_hash text NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'),
    generation bigint CHECK (generation > 0),
    task_id uuid REFERENCES fulfillment.tasks(task_id),
    decision_id uuid NOT NULL,
    decision_at timestamptz NOT NULL,
    result text NOT NULL CHECK (result IN ('APPLIED','ALREADY_APPLIED','REJECTED')),
    reason_code text,
    resulting_state text NOT NULL,
    response jsonb NOT NULL CHECK (jsonb_typeof(response) = 'object'),
    PRIMARY KEY (caller_id,action,order_id,command_key)
);
CREATE TABLE fulfillment.task_history (
    history_id uuid PRIMARY KEY,
    task_id uuid NOT NULL REFERENCES fulfillment.tasks(task_id),
    task_version bigint NOT NULL,
    action text NOT NULL,
    actor_id text NOT NULL,
    reason text,
    before_state jsonb NOT NULL,
    after_state jsonb NOT NULL,
    occurred_at timestamptz NOT NULL,
    UNIQUE (task_id,task_version)
);
CREATE TABLE fulfillment.inbox (
    source text NOT NULL,
    event_id text NOT NULL,
    payload_hash text NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'),
    payload bytea NOT NULL,
    topic text NOT NULL,
    partition_id integer NOT NULL CHECK (partition_id >= 0),
    offset_value bigint NOT NULL CHECK (offset_value >= 0),
    order_id uuid,
    source_version bigint,
    generation bigint,
    disposition text NOT NULL CHECK (disposition IN ('ACCEPTED','DEFERRED','QUARANTINED','IGNORED')),
    reason_code text,
    received_at timestamptz NOT NULL,
    PRIMARY KEY (source,event_id)
);
CREATE TABLE fulfillment.outbox (
    event_id uuid PRIMARY KEY,
    stream_id text NOT NULL,
    stream_version bigint NOT NULL CHECK (stream_version > 0),
    ordinal integer NOT NULL CHECK (ordinal >= 0),
    topic text NOT NULL,
    partition_key text NOT NULL,
    envelope jsonb NOT NULL CHECK (jsonb_typeof(envelope) = 'object'),
    occurred_at timestamptz NOT NULL,
    lease_owner text,
    lease_epoch bigint NOT NULL DEFAULT 0,
    lease_until timestamptz,
    attempts integer NOT NULL DEFAULT 0,
    next_run_at timestamptz NOT NULL,
    published_at timestamptz,
    UNIQUE (stream_id,stream_version,ordinal)
);
CREATE TABLE fulfillment.jobs (
    job_id uuid PRIMARY KEY,
    kind text NOT NULL,
    dedupe_key text NOT NULL UNIQUE,
    state text NOT NULL CHECK (state IN ('PENDING','RUNNING','RETRY_WAIT','SUCCEEDED','MANUAL_REVIEW')),
    stage text NOT NULL,
    order_id uuid,
    task_id uuid,
    input jsonb NOT NULL,
    command_key text,
    request_hash text,
    original_request jsonb,
    execution_attempts integer NOT NULL DEFAULT 0,
    reconciliation_attempts integer NOT NULL DEFAULT 0,
    last_outcome text,
    last_error_code text,
    next_run_at timestamptz NOT NULL,
    lease_owner text,
    lease_epoch bigint NOT NULL DEFAULT 0,
    lease_until timestamptz,
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL
);
CREATE TABLE fulfillment.audit_entries (
    audit_id uuid PRIMARY KEY,
    entity_id text NOT NULL,
    sequence bigint NOT NULL CHECK (sequence > 0),
    actor_id text NOT NULL,
    action text NOT NULL,
    reason text,
    redacted_before jsonb NOT NULL,
    redacted_after jsonb NOT NULL,
    prev_hash text NOT NULL CHECK (prev_hash ~ '^[0-9a-f]{64}$'),
    current_hash text NOT NULL CHECK (current_hash ~ '^[0-9a-f]{64}$'),
    occurred_at timestamptz NOT NULL,
    UNIQUE (entity_id,sequence)
);

CREATE INDEX task_queue ON fulfillment.tasks(warehouse_id,workflow_state,packing_due_at,admitted_at,task_id);
CREATE INDEX task_assignee_queue ON fulfillment.tasks(assignee_id,workflow_state,packing_due_at,task_id);
CREATE INDEX pending_outbox ON fulfillment.outbox(next_run_at,stream_id,stream_version,ordinal) WHERE published_at IS NULL;
CREATE INDEX runnable_jobs ON fulfillment.jobs(next_run_at,kind) WHERE state IN ('PENDING','RETRY_WAIT','MANUAL_REVIEW');
CREATE INDEX expired_job_leases ON fulfillment.jobs(lease_until) WHERE state = 'RUNNING';
CREATE INDEX media_cleanup ON fulfillment.media_files(status,session_expires_at) WHERE attached_at IS NULL AND legal_hold = false;

CREATE FUNCTION fulfillment.reject_immutable_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'immutable proof/audit row cannot be changed';
END;
$$;
CREATE TRIGGER task_revision_immutable BEFORE UPDATE OR DELETE ON fulfillment.task_revisions
    FOR EACH ROW EXECUTE FUNCTION fulfillment.reject_immutable_change();
CREATE TRIGGER audit_entry_immutable BEFORE UPDATE OR DELETE ON fulfillment.audit_entries
    FOR EACH ROW EXECUTE FUNCTION fulfillment.reject_immutable_change();
CREATE FUNCTION fulfillment.guard_monotonicity() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.highest_generation < OLD.highest_generation OR
       (OLD.accepted_task_id IS NOT NULL AND NEW.accepted_task_id IS DISTINCT FROM OLD.accepted_task_id) THEN
        RAISE EXCEPTION 'order guard cannot lose generation/accepted identity';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER guard_monotonic BEFORE UPDATE ON fulfillment.order_guards
    FOR EACH ROW EXECUTE FUNCTION fulfillment.guard_monotonicity();
CREATE FUNCTION fulfillment.admission_terminality() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF OLD.state IN ('ACCEPTED','CANCELLED') AND
       (NEW.state IS DISTINCT FROM OLD.state OR NEW.task_id IS DISTINCT FROM OLD.task_id OR
        NEW.decision_id IS DISTINCT FROM OLD.decision_id OR NEW.decision_at IS DISTINCT FROM OLD.decision_at) THEN
        RAISE EXCEPTION 'terminal admission decision cannot be rewritten';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER admission_terminal BEFORE UPDATE ON fulfillment.admissions
    FOR EACH ROW EXECUTE FUNCTION fulfillment.admission_terminality();
-- Cross-row quantities, task/package ownership of primary_evidence_id, allowed
-- workflow transitions, version increments, snapshot immutability and admission
-- linkage equality require application transactions + tests + restricted DB roles.
-- DELETE privileges for guards/admissions/registry/accepted identities are not
-- granted to the eventual runtime role; operational roles are configured later.
COMMIT;
